// 정명고등학교 (경기 부천시 소사구) - automatic high-school package (auto-school track, user decision 2026-10-23). Generated by jeongmyeong-local-builder
// from OSM building outlines and an estimated aerial work boundary + AWS Terrain Tiles: mapped candidate units destructible (grammar models, floors estimated),
// a baked ground (one terrain mesh with two drawn colour maps), fence / gates / stands / goals, trees and the extruded neighbourhood fading
// into the haze. Local only (registry public: false). Do not edit by hand - rerun the generator.
import { WORLD_UNITS_PER_METER, GEO_ORIGIN, JEONGMYEONG_PLACEMENTS, JEONGMYEONG_BUILDING_BASE, JEONGMYEONG_HEIGHT_GRIDS, JEONGMYEONG_HEIGHT_RANGE_M, JEONGMYEONG_ENV_IDS, JEONGMYEONG_DISPLAY, JEONGMYEONG_START_FRAME, JEONGMYEONG_OVERVIEW_AZIMUTH, JEONGMYEONG_CAMERA, JEONGMYEONG_PROVENANCE } from './data.js';
import { JEONGMYEONG_FOOTPRINTS } from './footprints.js';
import { JEONGMYEONG_PROTECTED } from './protected.js';

const MODEL_IDS = Object.freeze(JEONGMYEONG_PLACEMENTS.map(p => p.id));
const asset = file => new URL(`../../../assets/campuses/jeongmyeong/${file}`, import.meta.url).href;
const HAZE = JEONGMYEONG_DISPLAY.haze, FADE = JEONGMYEONG_DISPLAY.fade;

export const JEONGMYEONG = Object.freeze({
  id: 'jeongmyeong',
  meta: Object.freeze({ school: '정명고등학교', campus: '경기 부천시 소사구', short: '정명고', modelNoun: '정명고' }),
  geo: Object.freeze({ origin: GEO_ORIGIN, worldUnitsPerMeter: WORLD_UNITS_PER_METER }),
  placements: JEONGMYEONG_PLACEMENTS,
  approvedCount: JEONGMYEONG_PLACEMENTS.length,
  additionalCount: 0,
  coreIds: MODEL_IDS,
  startBuildingId: MODEL_IDS[0],
  // camera picked by scripts/auto-school/build.mjs from the measured occlusion (azimuths in radians, elevations in degrees, src/camera.js angles)
  view: Object.freeze({ get startFrame() { return (globalThis.innerWidth || 1280) < 600 ? {min: [-27, 2, -19], max: [-13, 8, 27], azimuth: 1.15, elevationDegrees: 12} : {min: [-29.4, -1, -3], max: [-2.4, 9, 43], azimuth: 1.45, elevationDegrees: 22}; }, overviewAzimuth: JEONGMYEONG_OVERVIEW_AZIMUTH }),
  camera: JEONGMYEONG_CAMERA,
  models: Object.freeze({
    manifests: Object.freeze([
      Object.freeze({ url: asset('manifest.json'), expectedIds: MODEL_IDS }),
      Object.freeze({ url: asset('environment.json'), expectedIds: JEONGMYEONG_ENV_IDS }),
    ]),
    proceduralIds: Object.freeze([]),
    createProceduralSource: () => { throw new Error('No procedural buildings in this campus'); },
    enhanceFacade: () => ({ stats: {}, dispose() {} }),
  }),
  terrain: Object.freeze({ heightGrids: JEONGMYEONG_HEIGHT_GRIDS, buildingBase: JEONGMYEONG_BUILDING_BASE, source: JEONGMYEONG_PROVENANCE.terrain }),
  environment: Object.freeze({ provenance: JEONGMYEONG_PROVENANCE, sourceNote: 'OSM ground surfaces and surroundings (© OpenStreetMap contributors, ODbL); heights, floors and planting estimated automatically' }),
  ground: Object.freeze({
    baked: Object.freeze({ envIds: JEONGMYEONG_ENV_IDS, castShadow: Object.freeze([]),
      fade: Object.freeze({ centre_m: Object.freeze([...FADE.centreEN]), near_m: FADE.r0_m, far_m: FADE.r1_m, linear: FADE.linearShare, colour: HAZE }), playMargin_m: 30,
      source: 'jeongmyeong-local-builder baked ground' }),
  }),
  protected: Object.freeze({ models: JEONGMYEONG_PROTECTED }),
  hazardTape: Object.freeze({ footprints: JEONGMYEONG_FOOTPRINTS }),
  scene: Object.freeze({
    background: HAZE, fog: Object.freeze({ color: HAZE, near: 500, far: 1400 }),
    hemisphere: Object.freeze({ sky: '#ffffff', ground: '#7d8a78', intensity: 1.35 }),
    sun: Object.freeze({ color: '#fff4e2', intensity: 3.1, position: Object.freeze([-110, 165, 140]), shadowSpan: 200 }),
    floor: Object.freeze({ color: '#c9cbc8', hidden: true, y: JEONGMYEONG_HEIGHT_RANGE_M[0] * WORLD_UNITS_PER_METER - .3 }),
  }),
});
export default JEONGMYEONG;
